// swift-tools-version: 6.1
import PackageDescription

let package = Package(
    name: "LRU",
    products: [.executable(name: "app", targets: ["app"])],
    targets: [
        .target(name: "AppCore", swiftSettings: [.enableUpcomingFeature("ExistentialAny")]),
        .executableTarget(name: "app", dependencies: ["AppCore"]),
    ]
)

/// A single parsed cache command.
public enum Command: Equatable {
    case set(key: Substring, value: Substring)
    case get(key: Substring)
    case delete(key: Substring)
    case size

    /// Parses one input line; returns `nil` for blank or malformed lines.
    public init?(line: Substring) {
        var rest = line[...]
        guard let name = Self.nextToken(&rest) else { return nil }
        let first = Self.nextToken(&rest)
        let second = Self.nextToken(&rest)
        guard Self.nextToken(&rest) == nil else { return nil }

        switch (name, first, second) {
        case let ("SET", key?, value?): self = .set(key: key, value: value)
        case let ("GET", key?, nil): self = .get(key: key)
        case let ("DEL", key?, nil): self = .delete(key: key)
        case ("SIZE", nil, nil): self = .size
        default: return nil
        }
    }

    /// Pops the next space-delimited token off the front of `text`.
    private static func nextToken(_ text: inout Substring) -> Substring? {
        let space = UInt8(ascii: " ")
        let utf8 = text.utf8
        guard let start = utf8.firstIndex(where: { $0 != space }) else {
            text = text[text.endIndex...]
            return nil
        }
        let end = utf8[start...].firstIndex(of: space) ?? utf8.endIndex
        defer { text = text[end...] }
        return text[start..<end]
    }
}

/// Drives an `LRUCache` from textual commands and produces textual output.
public struct CommandProcessor {
    private var cache: LRUCache<String, String>

    public init(capacity: Int) {
        cache = LRUCache(capacity: capacity)
    }

    /// Executes `command`, returning the line to print, if any.
    public mutating func execute(_ command: Command) -> String? {
        switch command {
        case let .set(key, value):
            cache.setValue(String(value), forKey: String(key))
            return nil
        case let .get(key):
            return cache.value(forKey: String(key)) ?? "NULL"
        case let .delete(key):
            return cache.removeValue(forKey: String(key)) ? "1" : "0"
        case .size:
            return String(cache.count)
        }
    }
}

/// Strips a trailing carriage return so CRLF input is handled gracefully.
public func normalizedLine(_ line: String) -> Substring {
    line.utf8.last == UInt8(ascii: "\r") ? line.dropLast() : line[...]
}

/// A fixed-capacity least-recently-used cache.
///
/// Entries live in a contiguous node pool linked into a doubly linked
/// recency list by index, and a dictionary maps keys to pool slots, so every
/// operation runs in O(1) expected time without per-entry allocations.
public struct LRUCache<Key: Hashable, Value> {
    private struct Node {
        var key: Key
        var value: Value
        var prev: Int
        var next: Int
    }

    private static var none: Int { -1 }

    public let capacity: Int
    private var index: [Key: Int] = [:]
    private var nodes: [Node] = []
    private var freeSlots: [Int] = []
    /// Most recently used node.
    private var head = LRUCache.none
    /// Least recently used node.
    private var tail = LRUCache.none

    public init(capacity: Int) {
        precondition(capacity > 0, "LRU capacity must be positive")
        self.capacity = capacity
        // Pre-size storage (bounded, so huge capacities stay lazy) to avoid
        // repeated rehashing and reallocation as the cache fills.
        let initial = Swift.min(capacity, 1 << 16)
        index.reserveCapacity(initial)
        nodes.reserveCapacity(initial)
    }

    public var count: Int { index.count }

    /// Returns the value for `key`, marking it as the most recently used.
    public mutating func value(forKey key: Key) -> Value? {
        guard let slot = index[key] else { return nil }
        moveToFront(slot)
        return nodes[slot].value
    }

    /// Inserts or overwrites `key`, marking it most recently used and evicting
    /// the least recently used entry if the capacity is exceeded.
    public mutating func setValue(_ value: Value, forKey key: Key) {
        if let slot = index[key] {
            nodes[slot].value = value
            moveToFront(slot)
            return
        }

        let slot: Int
        if index.count >= capacity {
            // Recycle the evicted node's slot for the new entry.
            slot = tail
            unlink(slot)
            index[nodes[slot].key] = nil
            nodes[slot] = Node(key: key, value: value, prev: Self.none, next: Self.none)
        } else if let reused = freeSlots.popLast() {
            slot = reused
            nodes[slot] = Node(key: key, value: value, prev: Self.none, next: Self.none)
        } else {
            slot = nodes.count
            nodes.append(Node(key: key, value: value, prev: Self.none, next: Self.none))
        }
        index[key] = slot
        pushFront(slot)
    }

    /// Removes `key`, returning whether it was present.
    @discardableResult
    public mutating func removeValue(forKey key: Key) -> Bool {
        guard let slot = index.removeValue(forKey: key) else { return false }
        unlink(slot)
        freeSlots.append(slot)
        return true
    }

    // MARK: - Recency list

    private mutating func moveToFront(_ slot: Int) {
        guard slot != head else { return }
        unlink(slot)
        pushFront(slot)
    }

    private mutating func pushFront(_ slot: Int) {
        nodes[slot].prev = Self.none
        nodes[slot].next = head
        if head != Self.none { nodes[head].prev = slot }
        head = slot
        if tail == Self.none { tail = slot }
    }

    private mutating func unlink(_ slot: Int) {
        let prev = nodes[slot].prev
        let next = nodes[slot].next
        if prev != Self.none { nodes[prev].next = next } else { head = next }
        if next != Self.none { nodes[next].prev = prev } else { tail = prev }
        nodes[slot].prev = Self.none
        nodes[slot].next = Self.none
    }
}

import AppCore

/// Buffers output and writes it in large chunks rather than per line.
struct OutputBuffer {
    private var buffer = ""
    private let flushThreshold = 1 << 16

    init() { buffer.reserveCapacity(flushThreshold + 128) }

    mutating func writeLine(_ line: String) {
        buffer += line
        buffer += "\n"
        if buffer.utf8.count >= flushThreshold { flush() }
    }

    mutating func flush() {
        guard !buffer.isEmpty else { return }
        print(buffer, terminator: "")
        buffer.removeAll(keepingCapacity: true)
    }
}

func run() {
    guard let header = readLine(),
          let capacity = Int(normalizedLine(header).filter { $0 != " " }),
          capacity > 0
    else { return }

    var processor = CommandProcessor(capacity: capacity)
    var output = OutputBuffer()

    while let line = readLine() {
        guard let command = Command(line: normalizedLine(line)) else { continue }
        if let result = processor.execute(command) {
            output.writeLine(result)
        }
    }
    output.flush()
}

run()
